  if self.items.is_multiple_of(256) { self.control.checkpoint(self.phase,self.items,0)?; }
  Ok(())
 }
}

fn admit_native(snapshot:&BcfSnapshot,phase:SqliteSnapshotPhase,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError> {
